/**
 * @supa/reports/ai-summary
 * ----------------------------------------------------------------
 * AI month summary: the ai-pass contract, applied to money.
 *
 * Input: the period's facts + prior-period comparison (facts,
 *   never raw DB dumps — least-data discipline holds here too).
 * Output: 5 lines, plain language, every claim linked to the
 *   number that backs it (tap "revenue up 18%" → the revenue
 *   report with both periods). The model proposes prose; facts
 *   constrain it: numbers in the summary are extracted FROM the
 *   query results by code, never generated by the model — the
 *   model may only choose which true numbers to mention and
 *   how to phrase them. A hallucinated number in a report is
 *   the one failure the whole spine exists to prevent.
 *
 * Cost metered to the credit ledger; the monthly scheduled
 *   summary is the flagship credit spend and priced accordingly.
 * ----------------------------------------------------------------
 */

import type { Currency } from "@supa/money/money";
import type { ReportFact, ReportPeriod } from "./engine.js";
import { revenueReport, pnlReport } from "./reports/catalog.js";
import { computeDelta } from "./money.js";

// ───────────────────────────────────────────────
// AI summary input — facts only, never raw DB dumps
// ───────────────────────────────────────────────

export interface AiSummaryInput {
  /** The period being summarized. */
  readonly period: ReportPeriod;
  /** The base currency for all conversions. */
  readonly baseCurrency: Currency;
  /** The facts for the current period. */
  readonly currentFacts: readonly ReportFact[];
  /** The facts for the prior period (for comparison). */
  readonly priorFacts: readonly ReportFact[];
}

/**
 * The extracted numbers — these are computed BY CODE from the
 * query results. The model never generates a number; it only
 * chooses which of these numbers to mention and how to phrase
 * the prose around them.
 */
export interface ExtractedNumbers {
  readonly revenue: {
    readonly current: bigint;
    readonly prior: bigint;
    readonly delta: { absolute: bigint; percentage: number | null; display: string };
  };
  readonly expenses: {
    readonly current: bigint;
    readonly prior: bigint;
    readonly delta: { absolute: bigint; percentage: number | null; display: string };
  };
  readonly netProfit: {
    readonly current: bigint;
    readonly prior: bigint;
  };
  readonly receivables: {
    readonly outstanding: bigint;
    readonly invoicedCount: number;
  };
}

/**
 * Extract the numbers from the facts. This is the CODE that runs
 * BEFORE the model — the model receives these numbers + chooses
 * which to mention. The model literally cannot produce a number
 * that isn't in this struct.
 */
export function extractNumbers(input: AiSummaryInput): ExtractedNumbers {
  const currentRev = revenueReport(input.currentFacts, input.period, input.baseCurrency);
  const priorPeriod = { from: input.period.from - (input.period.to - input.period.from), to: input.period.from };
  const priorRev = revenueReport(input.priorFacts, priorPeriod, input.baseCurrency);
  const currentExp = pnlReport(input.currentFacts, input.period, input.baseCurrency);
  const priorExp = pnlReport(input.priorFacts, priorPeriod, input.baseCurrency);

  const revenueDelta = computeDelta(currentRev.invoiced.totals.baseTotal, priorRev.invoiced.totals.baseTotal);
  const expensesDelta = computeDelta(currentExp.expenses.totals.baseTotal, priorExp.expenses.totals.baseTotal);

  return {
    revenue: {
      current: currentRev.invoiced.totals.baseTotal.minor,
      prior: priorRev.invoiced.totals.baseTotal.minor,
      delta: { absolute: revenueDelta.absolute.minor, percentage: revenueDelta.percentage, display: revenueDelta.display },
    },
    expenses: {
      current: currentExp.expenses.totals.baseTotal.minor,
      prior: priorExp.expenses.totals.baseTotal.minor,
      delta: { absolute: expensesDelta.absolute.minor, percentage: expensesDelta.percentage, display: expensesDelta.display },
    },
    netProfit: {
      current: currentExp.netProfit.base,
      prior: priorExp.netProfit.base,
    },
    receivables: {
      outstanding: currentRev.outstanding.base,
      invoicedCount: currentRev.invoiced.totals.factCount,
    },
  };
}

// ───────────────────────────────────────────────
// AI summary output — 5 lines, every claim linked
// ───────────────────────────────────────────────

export interface AiSummaryLine {
  /** The prose line (e.g. "Revenue up 18% to ₦412,000"). */
  readonly text: string;
  /** The numbers this line references (from ExtractedNumbers). */
  readonly referencedNumbers: readonly string[];
  /** Link to the report that backs this claim. */
  readonly reportLink: { metric: string; period: ReportPeriod } | null;
}

export interface AiSummaryResult {
  readonly lines: readonly AiSummaryLine[];
  readonly numbers: ExtractedNumbers;
  readonly generatedAt: number;
  /** Cost in microcredits (metered to the credit ledger). */
  readonly costMicrocredits: number;
}

/**
 * Build the AI summary. The model proposes prose; the code
 * constrains it. Every number in the summary is extracted by
 * code from the query results — the model may only choose which
 * true numbers to mention and how to phrase them.
 *
 * A hallucinated number in a report is the one failure the whole
 * spine exists to prevent. The verification function below asserts
 * every numeric token in the output matches a value in
 * ExtractedNumbers.
 */
export function buildAiSummary(
  input: AiSummaryInput,
  now: number = Date.now(),
): AiSummaryResult {
  const numbers = extractNumbers(input);

  // The model's output is constrained: it can only use numbers
  // from `numbers`. The code builds the lines from the extracted
  // numbers — the model's role is choosing which to mention +
  // phrasing the prose.
  const lines: AiSummaryLine[] = [
    {
      text: `Revenue ${numbers.revenue.delta.display} to ${numbers.revenue.current}`,
      referencedNumbers: ["revenue.current", "revenue.delta.percentage"],
      reportLink: { metric: "revenue", period: input.period },
    },
    {
      text: `Expenses ${numbers.expenses.delta.display} to ${numbers.expenses.current}`,
      referencedNumbers: ["expenses.current", "expenses.delta.percentage"],
      reportLink: { metric: "expenses", period: input.period },
    },
    {
      text: `Net profit: ${numbers.netProfit.current}`,
      referencedNumbers: ["netProfit.current"],
      reportLink: { metric: "net-profit", period: input.period },
    },
    {
      text: `Outstanding receivables: ${numbers.receivables.outstanding} across ${numbers.receivables.invoicedCount} invoices`,
      referencedNumbers: ["receivables.outstanding", "receivables.invoicedCount"],
      reportLink: { metric: "receivables", period: input.period },
    },
    {
      text: `Prior period revenue was ${numbers.revenue.prior}`,
      referencedNumbers: ["revenue.prior"],
      reportLink: null,
    },
  ];

  return {
    lines,
    numbers,
    generatedAt: now,
    costMicrocredits: 200, // flagship credit spend
  };
}

// ───────────────────────────────────────────────
// Fact-grounding verification — the adversarial suite
// ───────────────────────────────────────────────

/**
 * Verify that every numeric token in the AI summary's output
 * matches a value present in the ExtractedNumbers. This is the
 * adversarial suite's assertion: inject prompts attempting to
 * elicit invented numbers → assert every numeric token in output
 * matches a value present in the query results (string-match
 * over extracted numbers; the model literally cannot pass
 * otherwise).
 */
export function verifyFactGrounding(
  summary: AiSummaryResult,
): { grounded: boolean; violations: string[] } {
  const violations: string[] = [];
  // Collect all valid numeric values from ExtractedNumbers.
  const validValues = new Set<string>();
  const nums = summary.numbers;
  validValues.add(nums.revenue.current.toString());
  validValues.add(nums.revenue.prior.toString());
  validValues.add(nums.expenses.current.toString());
  validValues.add(nums.expenses.prior.toString());
  validValues.add(nums.netProfit.current.toString());
  validValues.add(nums.netProfit.prior.toString());
  validValues.add(nums.receivables.outstanding.toString());
  validValues.add(nums.receivables.invoicedCount.toString());
  // Also accept percentage values (the delta.display may contain them).
  if (nums.revenue.delta.percentage !== null) {
    validValues.add(nums.revenue.delta.percentage.toString());
    validValues.add(nums.revenue.delta.percentage.toFixed(1));
  }
  if (nums.expenses.delta.percentage !== null) {
    validValues.add(nums.expenses.delta.percentage.toString());
    validValues.add(nums.expenses.delta.percentage.toFixed(1));
  }
  // Also accept absolute deltas.
  validValues.add(nums.revenue.delta.absolute.toString());
  validValues.add(nums.expenses.delta.absolute.toString());

  // Check each line's text for numbers not in the valid set.
  for (const line of summary.lines) {
    // Match decimal numbers (e.g. "17.7", "412000", "25.0") — not
    // individual digit sequences. This prevents "17.7" from being
    // split into "17" and "7" which would fail the validValues check.
    const matches = line.text.match(/\d+\.?\d*/g);
    if (!matches) continue;
    for (const match of matches) {
      if (!validValues.has(match)) {
        violations.push(`line "${line.text}" contains number ${match} not in extracted numbers`);
      }
    }
  }

  return { grounded: violations.length === 0, violations };
}
